import java.util.*;

class Solution {
    public static int solve(Map<String,Object> data) {
        List<int[]> edges = (List<int[]>) data.get("edges");
        int left = (int) data.get("left");
        int right = (int) data.get("right");

        Arrays.sort(edges, Comparator.comparingInt(a -> a[0]));
        Set<Integer> used = new HashSet<>();
        int count = 0;

        for (int[] edge : edges) {
            if (!used.contains(edge[0])) {
                used.add(edge[0]);
                if (edge[1] <= right && !used.contains(edge[1])) {
                    used.add(edge[1]);
                    count++;
                }
            }
        }

        return count;
    }
}

import java.util.*;

class Solution {
    public static int solve(Map<String, Object> data) {
        int L = ((Integer) data.get("left")).intValue();
        int R = ((Integer) data.get("right")).intValue();
        List<int[]> edges = new ArrayList<>();

        for (Object edge : data.get("edges")) {
            edges.add(new int[]{((Integer) edge[0]).intValue(), ((Integer) edge[1]).intValue()});
        }

        Arrays.sort(edges, Comparator.comparingInt(a -> a[0]));

        int maxPairs = 0;
        int end = -1;

        for (int[] edge : edges) {
            if (edge[0] > end) {
                maxPairs++;
                end = edge[1];
            }
        }

        return maxPairs;
    }
}

import java.util.*;

class Solution {
    public static int solve(Map<String, Object> data) {
        int[] counts = new int[13];
        for (int[] e : (List<int[]>) data.get("edges")) {
            counts[e[0]]++;
            counts[e[1]]++;
        }
        int ans = 0;
        for (int i = 0; i < 13; i++) {
            if (counts[i] > 0) {
                ans += Math.min(counts[i], counts[12 - i]);
            }
        }
        return ans;
    }

    public static void main(String[] args) {
        System.out.println(solve(Map.of("edges", Collections.emptyList(), "left", 0, "right", 0))); // 0
        System.out.println(solve(Map.of("edges", Arrays.asList(new int[]{0, 0}, new int[]{1, 1}), "left", 2, "right", 2))); // 2
        System.out.println(solve(Map.of("edges", Arrays.asList(new int[]{0, 0}, new int[]{1, 0}), "left", 2, "right", 1))); // 1
        System.out.println(solve(Map.of("edges", Arrays.asList(new int[]{0, 0}, new int[]{0, 1}, new int[]{1, 1}, new int[]{2, 2}), "left", 3, "right", 3))); // 3
    }
}

import java.util.*;

public final class Solution {
    public static Object solve(Map<String,Object> data) {
        int L = ((Number)data.get("left")).intValue();
        int R = ((Number)data.get("right")).intValue();
        List<int[]> edges = (List<int[]>)data.get("edges");

        // Edge cases: empty or minimal inputs, boundary values, duplicates, large inputs
        if (L == 0 && R == 0 || edges.isEmpty()) return 0;

        // Brute-force approach: try all possible left-to-right pairs
        int maxPairs = 0;
        for (int i = 0; i < L; i++) {
            for (int j = i + 1; j <= R; j++) {
                boolean validPair = true;
                for (int[] edge : edges) {
                    if (edge[0] == i && edge[1] == j) {
                        validPair = false;
                        break;
                    }
                }
                if (validPair) maxPairs++;
            }
        }

        // Efficient solution: use a set to store used edges
        Set<Integer> usedEdges = new HashSet<>();
        for (int[] edge : edges) {
            usedEdges.add(edge[0]);
            usedEdges.add(edge[1]);
        }

        // Count the number of disjoint left-to-right pairs using the set
        int count = 0;
        for (int i = 0; i < L; i++) {
            for (int j = i + 1; j <= R; j++) {
                if (!usedEdges.contains(i * 10 + j)) {
                    count++;
                    usedEdges.add(i * 10 + j);
                }
            }
        }

        return count;
    }
}

